"""Get (int, string) tuple from int:str strings."""
def intstrtuple(s: Any) -> object {
    parts = [p.strip() for p in s.split(":", 1)];
    if (len(parts) == 2) {
        return (int(parts[0]), parts[1]);
    } else {
        return (None, parts[0]);
    }
}

